create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, role text check (role in ('buyer','creator')) default 'buyer', display_name text, created_at timestamptz default now());
create table if not exists public.listing_drafts (id uuid primary key default gen_random_uuid(), creator_id uuid not null references public.profiles(id) on delete cascade, status text not null check (status in ('draft','submitted','published')) default 'draft', product_name text not null, product_type text not null, outcome text not null, delivery text not null, preview_url text, included text[] default '{}', requirements text[] default '{}', boundary text[] default '{}', updated_at timestamptz default now(), created_at timestamptz default now());
alter table public.profiles enable row level security; alter table public.listing_drafts enable row level security;
create policy "users read own profile" on public.profiles for select using (auth.uid()=id); create policy "users update own profile" on public.profiles for update using (auth.uid()=id); create policy "creators manage own drafts" on public.listing_drafts for all using (auth.uid()=creator_id) with check (auth.uid()=creator_id);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id) values(new.id) on conflict do nothing; return new; end; $$;
create or replace trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
